CREATE OR REPLACE FUNCTION public.mcp_edit_product_metadata(p_code text, p_expected_updated_at timestamptz, p_name text DEFAULT NULL, p_description text DEFAULT NULL, p_confirm boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE old_product public.products%ROWTYPE; new_product public.products%ROWTYPE; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF; IF p_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Confirme explicitamente a edição'; END IF; IF p_name IS NULL AND p_description IS NULL THEN RAISE EXCEPTION 'Indique nome ou descrição'; END IF; IF p_name IS NOT NULL AND (length(trim(p_name)) = 0 OR length(p_name) > 500) THEN RAISE EXCEPTION 'Nome inválido'; END IF; IF length(p_description) > 5000 THEN RAISE EXCEPTION 'Descrição demasiado longa'; END IF; SELECT * INTO old_product FROM public.products WHERE code=p_code FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Produto não encontrado ou sem acesso'; END IF; IF old_product.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'O produto mudou; consulte novamente antes de editar'; END IF; UPDATE public.products SET name=COALESCE(p_name,name), description=COALESCE(p_description,description) WHERE id=old_product.id RETURNING * INTO new_product; IF NOT FOUND THEN RAISE EXCEPTION 'Sem permissão para editar este produto'; END IF; IF old_product.name IS DISTINCT FROM new_product.name THEN INSERT INTO public.product_changes(product_id,changed_by,change_type,field_changed,old_value,new_value) VALUES(old_product.id,auth.uid(),'update','name',old_product.name,new_product.name); END IF; IF old_product.description IS DISTINCT FROM new_product.description THEN INSERT INTO public.product_changes(product_id,changed_by,change_type,field_changed,old_value,new_value) VALUES(old_product.id,auth.uid(),'update','description',old_product.description,new_product.description); END IF; RETURN jsonb_build_object('code',new_product.code,'name',new_product.name,'description',new_product.description,'updated_at',new_product.updated_at); END; $$; REVOKE ALL ON FUNCTION public.mcp_edit_product_metadata(text,timestamptz,text,text,boolean) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.mcp_edit_product_metadata(text,timestamptz,text,text,boolean) TO authenticated;